create or replace TABLE KFL_PRODUCTION.DBP_DATA.MITARBEITERBEW (
	MITARBEITER_ID VARCHAR(20) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutige anonymisierte ID des Mitarbeiters',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahresmonat, z.Bsp 201308',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'PK - Mandant im DWH',
	ABWESENHEIT_TAGE NUMBER(9,2) NOT NULL COMMENT 'Abwesenheit in Kalendertagen',
	SOLL_STUNDEN_MONAT NUMBER(9,2) NOT NULL COMMENT 'Soll Stunden pro Monat',
	ABR_STUNDEN_MONAT NUMBER(9,2) NOT NULL COMMENT 'abgerechnete Stunden',
	LANGZEIT_ABWESEND_FG NUMBER(38,0) NOT NULL COMMENT 'Ist = 1, wenn der MA > 90 Tage abwesend ist. Redundant zur Performancesteigerung',
	NEU_MITARBEITER_FG NUMBER(38,0) NOT NULL COMMENT 'Ist = 1, wenn der MA < 6 Monate im Unternehmen ist. Redundant zur Performancesteigerung',
	KRANK_TAGE NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Errechnet aus der Summe der Abwesenheitsarten mit der Bedeutung \"krank\"',
	TEILZEIT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist = 1, wenn der MA in Teilzeit (Beschäftigungsgrad < 100) ist und somit ein X geliefert wird.',
	HR_OBJEKT_ID NUMBER(18,0) NOT NULL COMMENT 'Objekt ID, 8-stellige Zahl',
	MA_STATUS_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'ID des Mitarbeiterstatus',
	GESCHLECHT_ID NUMBER(38,0) NOT NULL COMMENT 'ID des Geschlechts',
	TARIFGEBIET_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'ID des Tarifgebiets',
	SHR_MA_FUNKTION_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Funktionsschlüssel des Mitarbeiters aus zhr_fsl',
	TARIFART_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'ID der Tarifart aus trfar, z.Bsp. ''GH''',
	UNTERNEHMENS_BEREICH_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'ID des Unternehmensbereichs aus zhr_division, z.Bsp. 23',
	GEHALTS_REGION_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'ID der Gehaltsregion aus region',
	HAUS_KATEGORIE_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'ID der Hauskategorie aus house_cat',
	HAUPT_MITARBEITER_ID VARCHAR(20) NOT NULL COLLATE 'en-ci' COMMENT 'Hauptpersonalnummer aus hpern. MA mit mehreren Personalnummern besitzen eine Hauptnummer. In der Regel ist hier die mitarbeiter_id gespeichert.',
	SOLL_KALENDER_TAGE NUMBER(9,2) NOT NULL COMMENT 'Sollarbeit in Kalendertagen aus ksoll',
	RESTURLAUB_VJ NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Resturlaub aus den Vorjahren in Tagen aus mbnum',
	RESTURLAUB_AKT_KJ NUMBER(9,2) NOT NULL COMMENT 'Resturlaub aus dem aktuellen Kalenderjahr in Tagen',
	ANSPRUCH_URLAUB_AKT_KJ NUMBER(9,2) NOT NULL COMMENT 'Urlaubsanspruch im aktuellen Kalenderjahrin Tagen',
	LANGZEIT_KRANK_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	MUTTERSCHUTZ_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	BESCHAEFTIGUNGS_VERBOT_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	AUSHILFE_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	ELTERNZEIT_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	GRUNDWEHRDIENST_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	ATZ_KZ NUMBER(38,0) NOT NULL COMMENT 'Altersteilzeit Kennzeichen: 0 = kein ATZ, 1 = aktiv, 2 = passiv',
	FREIGESTELLT_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	IMPATRIATES_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	EXTERNE_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	AZUBI_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	MA_EINTRITT_KZ NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = Eintritt von intern, 2 = Eintritt von extern',
	MA_AUSTRITT_KZ NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = Austritt nach intern, 2 = Austritt nach extern',
	FLUKTUATION_KZ NUMBER(38,0) NOT NULL COMMENT 'Bedeutungen: 0 = nicht ausgetreten, 1 = Fluktuation  Arbeitnehmer  2 = Fluktuation  Arbeitgeber',
	KI_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichnet Mitarbeiter von Kaufland International. 0 = trifft nicht zu, 1 = trifft zu',
	GENOMMEN_URLAUB NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'genommener Urlaub auf den Monat bezogen, errechnet aus Abwesenheiten',
	INVENTUR_AUSHILFE_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	TIP_AUSTRAEGER_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	TIP_KONTROLLEUR_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	TIP_GEBIETSBETREUER_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	DIPLOMAND_PRAKTIKANT_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	PRAKTIKANT_O_ENTGELD_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	EXPATRIATES_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	HINTERBLIEBENE_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	VERSORGUNGSBEZIEHER_FG NUMBER(38,0) NOT NULL COMMENT '0 = trifft nicht zu, 1 = trifft zu',
	SOLL_ARBEITSTAGE NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Soll-Arbeitstage im Monat aus dem Quellfeld asoll',
	SB_PROZENT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Grad der Schwerbehinderung (Prozentsatz) aus der Quelle p0004.sbpro',
	ARBEITSZEIT_ANTEIL NUMBER(9,2) COMMENT 'Arbeitszeit-Anteil aus der Quelle p0000,arbant',
	ABWESENHEIT_ARBEITSTAGE_BEZ NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'bezahlte Abwesenheitstage in Arbeitstagen.Wird über die Lohnart 7728 ermittelt',
	ABWESENHEIT_ARBEITSTAGE_UNBEZ NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'unbezahlte Abwesenheitstage in Arbeitstagen.Wird über die Lohnart 7729 ermittelt',
	ARB_STUNDEN_TAG NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Arbeitsstunden pro Tag aus der Quelle arbst',
	KRANK_TAGE_ARBEITSTAGE NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Summierung auf MA/ Monat der Krankheitstage (Arbeitstage Filter nach Abwesehentsart)',
	ANZ_ARBEITS_UNFALL NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl der Arbeitsunfälle, redundant, wird ermittelt aus Abwesenheitsart in der Tabelle ma_abwesenh_zu_per',
	VERTRAGSENDE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag gesetzt, wenn Datum Vertragsende < 6 Monate. Redundant. Wird ermittelt aus ma_datumsart_zu_per',
	UNTERMONATLICH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist gesetzt bei Austritt innerhalb eines Monats. Redundant. Wird aus l_ma_status ermittelt.',
	AUSHILFE_NICHT_GEARBEITET_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Redundant. Wird über ma_lohnart_zu_per ermittelt',
	ABWESENHEIT_STUNDEN NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Abwesenheitsstunden Mitarbeiter auf Ebene Abwesenheitsart aus SAP HCM Infotyp 2001',
	SONSTIGE_ABWESENHEIT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist=1, wenn eine Abwesenheitsart der Kategorie sonstige Abwesenheit im Abrechnungsmonat gepflegt ist.',
	PFLEGE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist=1, wenn eine Abwesenheitsart der Kategorie Pflege im Abrechnungsmonat gepflegt ist.',
	KRANKHEIT_UNFALL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist=1, wenn eine Abwesenheitsart der Kategorie Krankheit oder Unfall im Abrechnungsmonat gepflegt ist.',
	LANGZEIT_ABWESENHEIT_TAGE NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Durchgängige Abwesenheitstage bis Monatsende',
	LANGZEIT_ABWESENHEIT_TAGE_KUM NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Kummulierte Abwesenheitstage der Monate ohne Unterbrechung',
	LANGZEIT_MIN_DAT DATE COMMENT 'Tag, an dem die durchgängige Abwesenheit begonnen wurde',
	LANGZEIT_ABWESENHEIT_GRUND VARCHAR(255) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Begründung der Unterbrechung',
	STICHTAG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist=1, wenn entsprechende Abwesenheitsart die der Stichtagslogik folgt, im Abrechnungsmonat gepflegt ist.',
	DAT_LETZTE_ABWESENHEIT DATE COMMENT 'Datum des letzten Tages der Abwesenheit eines Mitarbeiters im entsprechenden KJ-Monat',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	MITARBEITER_ALTER NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Alter des Mitarbeiters ',
	constraint PK_MITARBEITERBEW primary key (MITARBEITER_ID, KJMO, MANDANT_ID)
)COMMENT='SHR - Bewegungsdaten der Mitarbeiter'
;